import{_ as i,c as a,o as n,a2 as s}from"./chunks/framework.jqDK1qTK.js";const k=JSON.parse('{"title":"Operations","description":"","frontmatter":{"github_repo":"https://github.com/gardener/gardener-extension-networking-calico","github_subdir":"docs/operations","params":{"github_branch":"master"},"path_base_for_github_subdir":{"from":"content/docs/extensions/network-extensions/gardener-extension-networking-calico/operations.md","to":"operations.md"},"persona":"Operators","title":"Operations","prev":false,"next":false},"headers":[],"relativePath":"docs/extensions/network-extensions/gardener-extension-networking-calico/operations/index.md","filePath":"docs/extensions/network-extensions/gardener-extension-networking-calico/operations.md","lastUpdated":null}'),t={name:"docs/extensions/network-extensions/gardener-extension-networking-calico/operations/index.md"};function o(r,e,l,h,p,d){return n(),a("div",null,e[0]||(e[0]=[s(`<h1 id="using-the-calico-networking-extension-with-gardener-as-operator" tabindex="-1">Using the Calico networking extension with Gardener as operator <a class="header-anchor" href="#using-the-calico-networking-extension-with-gardener-as-operator" aria-label="Permalink to &quot;Using the Calico networking extension with Gardener as operator&quot;">​</a></h1><p>This document explains configuration options supported by the networking-calico extension.</p><h3 id="run-calico-node-in-non-privileged-and-non-root-mode" tabindex="-1">Run calico-node in non-privileged and non-root mode <a class="header-anchor" href="#run-calico-node-in-non-privileged-and-non-root-mode" aria-label="Permalink to &quot;Run calico-node in non-privileged and non-root mode&quot;">​</a></h3><p><strong>Feature State</strong>: <code>Alpha</code></p><h5 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h5><p>Running containers in privileged mode is not recommended as privileged containers run with all <a href="https://man7.org/linux/man-pages/man7/capabilities.7.html" target="_blank" rel="noreferrer">linux capabilities</a> enabled and can access the host&#39;s resources. Running containers in privileged mode opens number of security threats such as breakout to underlying host OS.</p><h5 id="support-for-non-privileged-and-non-root-mode" tabindex="-1">Support for non-privileged and non-root mode <a class="header-anchor" href="#support-for-non-privileged-and-non-root-mode" aria-label="Permalink to &quot;Support for non-privileged and non-root mode&quot;">​</a></h5><p>The Calico project has a preliminary support for running the calico-node component in non-privileged mode (see <a href="https://projectcalico.docs.tigera.io/security/non-privileged" target="_blank" rel="noreferrer">this guide</a>). Similar to <a href="https://github.com/tigera/operator" target="_blank" rel="noreferrer">Tigera Calico operator</a> the networking-calico extension can also run calico-node in non-privileged and non-root mode. This feature is controller via feature gate named <code>NonPrivilegedCalicoNode</code>. The feature gates are configured in the <a href="https://github.com/gardener/gardener-extension-networking-calico/blob/master/example/00-componentconfig.yaml" target="_blank" rel="noreferrer">ControllerConfiguration</a> of networking-calico. The corresponding ControllerDeployment configuration that enables the <code>NonPrivilegedCalicoNode</code> would look like:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">apiVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">core.gardener.cloud/v1beta1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ControllerDeployment</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metadata</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">networking-calico</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">helm</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">providerConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  values</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    chart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;omitted&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      featureGates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        NonPrivilegedCalicoNode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><h5 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h5><ul><li>The support for the non-privileged mode in the Calico project is not ready for productive usage. The <a href="https://projectcalico.docs.tigera.io/security/non-privileged" target="_blank" rel="noreferrer">upstream documentation</a> states that in non-privileged mode the support for features added after Calico v3.21 is not guaranteed.</li><li>Calico in non-privileged mode does not support eBPF dataplane. That&#39;s why when eBPF dataplane is enabled, calico-node has to run in privileged mode (even when the <code>NonPrivilegedCalicoNode</code> feature gate is enabled).</li><li>(At the time of writing this guide) there is the following issue <a href="https://github.com/projectcalico/calico/issues/5348" target="_blank" rel="noreferrer">projectcalico/calico#5348</a> that is not addressed.</li><li>(At the time of writing this guide) the upstream adoptions seems to be low. The Calico charts and manifest in <a href="https://github.com/projectcalico/calico" target="_blank" rel="noreferrer">projectcalico/calico</a> run calico-node in privileged mode.</li></ul><h3 id="seamless-overlay-network-mode-switching" tabindex="-1">Seamless overlay network mode switching <a class="header-anchor" href="#seamless-overlay-network-mode-switching" aria-label="Permalink to &quot;Seamless overlay network mode switching&quot;">​</a></h3><p><strong>Feature State</strong>: <code>Alpha</code></p><h5 id="motivation-1" tabindex="-1">Motivation <a class="header-anchor" href="#motivation-1" aria-label="Permalink to &quot;Motivation&quot;">​</a></h5><p>When switching Calico from overlay mode (IPIP) to non-overlay mode, there is a critical transition period where pod-to-pod communication can be disrupted if the network routes are not properly configured. In non-overlay mode, Calico relies on the cloud provider&#39;s route controller to create routes for pod-to-pod communication. If overlay is disabled before these routes are created, pods may lose connectivity.</p><h5 id="support-for-seamless-overlay-switching" tabindex="-1">Support for seamless overlay switching <a class="header-anchor" href="#support-for-seamless-overlay-switching" aria-label="Permalink to &quot;Support for seamless overlay switching&quot;">​</a></h5><p>The <code>SeamlessOverlaySwitch</code> feature gate enables validation of node routes before disabling overlay networking. When this feature is enabled and an overlay-to-non-overlay switch is detected, the extension will:</p><ol><li>Check that all nodes have the <code>NetworkUnavailable</code> condition set to <code>False</code> with reason <code>RouteCreated</code></li><li>Only proceed with disabling overlay once routes are confirmed to be in place</li></ol><p>This prevents connectivity issues during the transition period. The feature is controlled via feature gate named <code>SeamlessOverlaySwitch</code>. The feature gates are configured in the <a href="https://github.com/gardener/gardener-extension-networking-calico/blob/master/example/00-componentconfig.yaml" target="_blank" rel="noreferrer">ControllerConfiguration</a> of networking-calico. The corresponding ControllerDeployment configuration that enables the <code>SeamlessOverlaySwitch</code> would look like:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">apiVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">core.gardener.cloud/v1beta1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ControllerDeployment</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metadata</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">networking-calico</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">helm</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">providerConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  values</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    chart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;omitted&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      featureGates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        SeamlessOverlaySwitch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>Note: Seamless overlay switching requires the shoot Kubernetes cluster to be running Kubernetes &gt;= 1.36 or to have the MutatingAdmissionPolicy admission feature enabled in the kube-apiserver (feature gate and RuntimeConfig). Without one of these, the extension cannot use the newer admission APIs needed for the seamless switch.</p><h5 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h5><ul><li><strong>Enabled</strong> (default): The extension validates that routes are created before disabling overlay. If routes are not ready, the reconciliation will fail with a retriable error, keeping overlay enabled until routes are confirmed.</li><li><strong>Disabled</strong>: The extension will disable overlay immediately when requested, without checking for route readiness. This may result in temporary connectivity issues during the transition.</li></ul><h5 id="limitations-1" tabindex="-1">Limitations <a class="header-anchor" href="#limitations-1" aria-label="Permalink to &quot;Limitations&quot;">​</a></h5><p>This validation only applies when switching from overlay-enabled to overlay-disabled. It does not affect other configuration changes.</p>`,25)]))}const g=i(t,[["render",o]]);export{k as __pageData,g as default};
